",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"315011",1}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"315011",2}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"315011",6}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition4={relation="and",conditions={{type="equaltab",args={"315011",8}}}},autoResult4={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc03={id="rwnpc03",baseId="rwnpc04",combatid={1,1001},name="箫秋山",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL平遥公主：今日江湖各路英雄齐聚于此，实乃一大盛事，我也不再赘言，这便开宴！NOR"}},{type="gaintab",args={"315011",1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"CYN只见众人正饮酒作乐，谈笑风生,清如水忽然起身，款步走向放置古琴之处。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL清如水：小女子愿为诸位弹曲助兴。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN清如水素手轻抚琴弦，琴音缓缓，宛如涓涓细流。初时，众人只觉这琴音美妙动听，然而，随着琴音袅袅，众人竟渐渐觉得脑袋昏沉起来，内息亦是紊乱不稳。NOR"}},{type="gaintab",args={"315011",2}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL箫秋山：师妹？你这是何意？NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL箫秋山：师妹，不要执迷不悟，一错再错！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL清如水：哼！这些个江湖中人，有一个算一个，都是贪得无厌之徒，谁都配不上隐脉图！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL箫秋山：清如水，你这是一孔之见，太过狭隘！更何况师父的遗愿，就是让隐脉图名扬天下！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL清如水：是你和师父都太过天真！独我一人，亦可以让它名扬天下！废话少说，箫秋山，我要你亲手毁了这隐脉图碑！并交出《隐脉图》原本！不然，我就只能从公主开始下手！NOR"}},{type="gaintab",args={"315011",4}},{type="refresh",args={}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL箫秋山：师妹，你这般做，可想过后果？NOR"}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"YEL箫秋山：我和她早有分歧，只是没想到她执念如此之深……不，应该是，我们的执念都是如此之深。NOR"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"315011",1}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"315011",2}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"315011",3}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition4={relation="and",conditions={{type="equaltab",args={"315011",4}}}},autoResult4={{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},autoCondition5={relation="and",conditions={{type="equaltab",args={"315011",6}}}},autoResult5={{type="showbutton",args={4,0}},{type="showbutton",args={5,0}},{type="showbutton",args={6,1}}},autoCondition6={relation="and",conditions={{type="equaltab",args={"315011",7}}}},autoResult6={{type="change",args={"rwnpc03","rwnpc03a"}}},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc04={id="rwnpc04",baseId="rwnpc03",combatid={1,1001},name="清如水",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1=